    'home.arenaTitle': 'Elige tu Arena (21 Juegos)',
    'home.arenaDesc': 'Cada juego cuenta con física canvas 2D única, animaciones visuales y 5 niveles de dificultad.',
    'home.searchPlaceholder': 'Buscar juegos, etiquetas, géneros...',
    'home.noGamesFound': 'No se encontraron juegos coincidentes',
    'home.noGamesDesc': 'Intenta borrar tu búsqueda o cambiar la categoría del filtro.',
    'home.engBadge': 'Ingeniería y Física',
    'home.engTitle': 'Diseñado para velocidad, ritmo y precisión.',
    'home.engDesc': 'Cero sobrecarga, renderizado canvas puro a más de 60 FPS y retroalimentación acústica auténtica con Web Audio API.',
    'home.pillar1Title': 'Audio de Interruptores Sintetizado',
    'home.pillar1Desc': 'Clics y thocks sintetizados en tiempo real. Cambia entre Blue Clicky, Panda Thock, Linear Red o máquinas de escribir.',
    'home.pillar2Title': 'Telemetría en Vivo y Delta PPM',
    'home.pillar2Desc': 'El cálculo de tiempos a nivel de submilisegundos mide PPM brutas, PPM netas y curvas de precisión mientras juegas.',
    'home.pillar3Title': '105 Niveles Progresivos',
    'home.pillar3Desc': 'Cada uno de los 21 juegos ofrece 5 niveles distintos, desde ejercicios suaves de 30 PPM hasta batallas contra jefes de 100+ PPM.',
    'home.speedSuiteBadge': 'Suite Profesional de Test de Velocidad',
    'home.speedThemes': '17 Temas',
    'home.speedZeroLatency': 'Cero Latencia',
    'home.speedBenchTitle': 'Banco de Pruebas de Velocidad en Vivo.',
    'home.speedBenchDesc': 'Mide tus Palabras Por Minuto (PPM), consistencia de ritmo y precisión en tiempo real con temas visuales y telemetría avanzada.',
    'home.noviceTier': '🌱 Principiante: 0–35 PPM',
    'home.averageTier': '🎯 Promedio: 40–55 PPM',
    'home.proTier': '⚡ Pro: 60–85 PPM',
    'home.titanTier': '👑 Titán: 100+ PPM',
    'home.guideBadge': '📖 LA GUÍA COMPLETA DEL TECLADO',
    'home.guideTitle': 'Domina el Teclado con Typing Game Zone: La Mejor Plataforma Gratuita de Juegos de Mecanografía 2D Online',
    'home.guideSubtitle': 'Descubre cómo las batallas arcade 2D, las pruebas de velocidad y las lecciones de mecanografía al tacto se combinan para acelerar tu velocidad y precisión.',
    'home.sub1Title': 'Revolucionando la Mecanografía Online Mediante Mecánicas Arcade 2D Gamificadas',
    'home.sub1Html': 'Bienvenido a <strong>Typing Game Zone</strong>, la plataforma líder de arcade digital y pruebas de velocidad diseñada para revolucionar cómo estudiantes, desarrolladores y mecanógrafos dominan el teclado. Durante décadas, aprender a escribir se ha basado en ejercicios aburridos y tutores repetitivos. <strong>Typing Game Zone</strong> transforma la <strong>mecanografía online</strong> al combinar mecánicas de juegos arcade 2D, imágenes dinámicas, audio sintetizado y lecciones estructuradas en una suite web inmersiva de 21 títulos.',
    'home.sub2Title': '¿Por qué Jugar Juegos de Mecanografía 2D Online? El Poder de Aprender Jugando',
    'home.sub2Html1': 'Dominar la mecanografía requiere memoria neuromuscular profunda. Al practicar con texto estático, la mente se distrae. Entrar en un juego de mecanografía 2D cambia la psicología del aprendizaje: el cerebro se activa resolviendo problemas y reaccionando a estímulos espaciales rápidos.',
    'home.sub2Html2': 'Nuestra colección ofrece un rendimiento de 60 FPS sin latencia. Enfréntate a la horda zombie defendiendo con palabras bala, guía a la serpiente en el laberinto o resuelve enigmas deduciendo palabras clave.',
    'home.sub2Card1Title': '🧟 Horda Zombie',
    'home.sub2Card1Desc': 'Mecánica de disparos de supervivencia donde una alta velocidad de PPM repele enjambres.',
    'home.sub2Card2Title': '🐍 Arena de la Serpiente',
    'home.sub2Card2Desc': 'Navegación retro en laberintos que exige comandos de teclado inmediatos.',
    'home.sub2Card3Title': '🕵️ Adivina Quién Soy',
    'home.sub2Card3Desc': 'Acertijos y desafíos de deducción rápida mediante palabras clave.',
    'home.sub3Title': 'Lecciones de Mecanografía Estructuradas y Laboratorio de Práctica Interactivo',
    'home.sub3Html': 'Lograr fluidez profesional exige ergonomía adecuada y técnica de mecanografía al tacto sin mirar el teclado. En nuestro Laboratorio de Práctica dominarás la matriz QWERTY y asignarás cada tecla a su cuadrante de dedo óptimo con diagnósticos inteligentes en tiempo real.',
    'home.sub4Title': 'Juegos de Mecanografía Divertidos para Niños: Seguros y Educativos',
    'home.sub4Html': 'En la era digital actual, la fluidez con el teclado es esencial para los estudiantes. Typing Game Zone ofrece juegos coloridos con 5 niveles de dificultad que ayudan a los niños a mejorar su motricidad fina y ortografía en un entorno libre de anuncios.',
    'home.sub5Title': 'Dominando la Velocidad de Palabras y Pruebas de Rendimiento',
    'home.sub5Html': 'Para superar las 80 a 120+ PPM, el reconocimiento de palabras completas es clave. Inspirado en benchmarks como Typing Master y Monkeytype, nuestro banco de pruebas mide velocidad y precisión en intervalos de 15s, 30s y 60s con síntesis de audio de interruptores mecánicos.',
    'home.sub6Title': 'Por Qué Typing Game Zone es 100% Gratuito y Accesible para Todos',
    'home.sub6Html': 'Creemos que la educación de mecanografía de primer nivel debe ser accesible para todos. Sin muros de pago, suscripciones ni descargas: juega directamente en tu navegador en ordenador, portátil, Chromebook o tableta con 17 temas de color y 16 idiomas.',
