    'game.word-tetris.title': 'Wort-Tetris',
    'game.word-tetris.desc': 'Tippe fallende Wort-Tetrominos ab, um Zeilen aufzulösen, bevor sie die Decke berühren.',
    'game.rhythm-beat.title': 'Rhythm Beat Typer',
    'game.rhythm-beat.desc': '4-Spur-Synthwave-Musiktitel. Triff Worte im Takt bei eskalierendem BPM-Tempo.',
