    'game.key-master.desc': 'Interaktive 3D-Tastatur-Heatmap, Fingerplatzierungszonen und gezielte Genauigkeitsübungen.',
    'home.library': 'Spiele-Bibliothek',
    'home.arenaTitle': 'Wähle deine Arena (21 Spiele)',
    'home.arenaDesc': 'Jedes Spiel bietet einzigartige 2D-Canvas-Physik, visuelle Animationen und adaptives WPM-Balancing.',
    'home.searchPlaceholder': 'Spiele, Tags, Genres suchen...',
