    'home.engBadge': 'Entwicklung & Physik',
    'home.engTitle': 'Entwickelt für Geschwindigkeit, Rhythmus und Präzision.',
    'home.engDesc': 'Kein unnötiger Ballast, reines Canvas-Rendering mit 60+ FPS und authentische mechanische Schalter-Synthese.',
    'home.pillar1Title': 'Prozeduraler Schalter-Sound',
    'home.pillar1Desc': 'Echtzeit-synthetisierte Klicks und Thocks. Wechsle sofort zwischen Cherry MX Blue, Holy Panda und Schreibmaschine.',
    'home.pillar2Title': 'Live-Telemetrie & Delta-WPM',
    'home.pillar2Desc': 'Sub-Millisekunden-Timing berechnet Brutto-WPM, Netto-WPM, Genauigkeit und Rhythmus-Konsistenz.',
    'home.pillar3Title': '105 Mehrstufige Level',
    'home.pillar3Desc': 'Jedes der 21 Spiele enthält 5 Stufen, von 30 WPM für Anfänger bis zu 100+ WPM für Titanen.',
    'home.speedSuiteBadge': 'Pro Speed Test Suite',
