    'home.speedBenchDesc': 'Teste deine Wörter pro Minute (WPM), Tippkadenz und Genauigkeit in 15s-, 30s- oder 60s-Sprints.',
    'home.noviceTier': '🌱 Anfänger: 0–35 WPM',
    'home.averageTier': '🎯 Durchschnitt: 40–55 WPM',
    'home.proTier': '⚡ Profi: 60–85 WPM',
    'home.titanTier': '👑 Titan: 100+ WPM',
    'home.guideBadge': '📖 DER KOMPLETTE TASTATUR-LEITFADEN',
    'home.guideTitle': 'Meistere die Tastatur mit Typing Game Zone: Das ultimative kostenlose Arcade-Portal',
    'home.guideSubtitle': 'Erfahre, wie 2D-Arcade-Schlachten, Geschwindigkeitstests und strukturiertes Zehnfingersystem deine Tippgeschwindigkeit verdoppeln.',
    'home.sub1Title': 'Revolution des Online-Tippens durch spielerische 2D-Arcade-Mechaniken',
    'home.sub1Html': 'Willkommen bei <strong>Typing Game Zone</strong>, dem weltweit führenden Portal für modernes Tastaturschreiben und Arcade-Action. Im Gegensatz zu langweiligen traditionellen Texteditoren kombiniert unsere Plattform <strong>laborgenaue WPM-Telemetrie</strong> mit spannendem 2D-Gameplay.',
    'home.sub2Title': 'Warum 2D-Tippspiele online spielen? Die Kraft des spielerischen Zehnfingersystems',
    'home.sub2Html1': 'Das Beherrschen des <strong>Tastaturschreibens</strong> erfordert den Aufbau von Muskelgedächtnis über motorische Rhythmen. Wenn man unter Druck tippt, wird die visuelle Tastatursuche durch reflexartiges Tippen ersetzt.',
    'home.sub2Html2': 'Unsere Sammlung von <strong>2D-Online-Tippspielen</strong> fordert das periphere Sehen und die Reaktionszeit heraus:',
    'home.sub2Card1Title': '🧟 Zombie Horde',
    'home.sub2Card1Desc': 'Survival-Shooter-Mechanik: Hohe WPM halten feindliche Wellen zurück.',
    'home.sub2Card2Title': '🐍 Snake Arena',
    'home.sub2Card2Desc': 'Retro-Labyrinth: Sofortige Richtungswechsel durch exakte Anschläge.',
    'home.sub2Card3Title': '🕵️ Guess Who I Am',
    'home.sub2Card3Desc': 'Rätselhinweise und deduktives Wortschreiben gegen die Uhr.',
    'home.sub3Title': 'Strukturierte Tipplektionen und das interaktive Übungslabor',
    'home.sub3Html': 'Ergonomische Handhaltung ist das Fundament für 100+ WPM. Unser <strong>Übungslabor</strong> bietet eine visuelle Heatmap der Grundreihe (ASDF JKL;), damit jeder Finger die richtige Taste trifft.',
    'home.sub4Title': 'Spannende Online-Tippspiele für Kinder: Sicher, lehrreich und unterhaltsam',
    'home.sub4Html': 'Tastaturkompetenz ist eine der wichtigsten digitalen Grundfähigkeiten für Schule und Zukunft. Unsere Spiele sind gewaltfrei gestaltet und fördern Sprachverständnis und Rechtschreibung.',
    'home.sub5Title': 'Wortgeschwindigkeit meistern und Tippmeister-Benchmarks erreichen',
    'home.sub5Html': 'Um Geschwindigkeiten von 80 bis 120+ WPM zu erreichen, liest das Gehirn ganze Wortblöcke voraus. Unser Echtzeit-Geschwindigkeitstest liefert präzise Metriken zu Latenz und Konsistenz.',
    'home.sub6Title': 'Warum Typing Game Zone für jeden kostenlos zugänglich ist',
    'home.sub6Html': 'Wir glauben, dass erstklassiges Tastaturtraining ohne Paywalls oder Abonnements für jeden weltweit frei im Browser verfügbar sein sollte.',
