    'home.pillar1Desc': 'Cliques e batidas sintetizados em tempo real. Alterne instantaneamente entre Cherry MX Blue, Panda e máquina de escrever.',
    'home.pillar2Title': 'Telemetria ao Vivo & Delta PPM',
    'home.pillar2Desc': 'Temporização precisa de milissegundos calcula PPM bruto, PPM líquido, precisão e consistência de cadência.',
    'home.pillar3Title': '105 Níveis Progressivos',
    'home.pillar3Desc': 'Cada um dos 21 jogos possui 5 níveis distintos, escalando de 30 PPM para iniciantes até 100+ PPM para titãs.',
