    'home.speedBenchTitle': 'Bancada de Teste de Velocidade ao Vivo.',
    'home.speedBenchDesc': 'Avalie suas Palavras Por Minuto (PPM), consistência de digitação e precisão em testes de 15s, 30s ou 60s.',
