    'home.titanTier': '👑 Titã: 100+ PPM',
    'home.guideBadge': '📖 GUIA COMPLETO DE TECLADO',
    'home.guideTitle': 'Domine o Teclado com Typing Game Zone: O Portal Definitivo de Arcade Grátis',
    'home.guideSubtitle': 'Descubra como batalhas arcade em 2D, testes de velocidade e digitação tátil dobram sua agilidade no teclado.',
    'home.sub1Title': 'Revolucionando a Digitação Online com Mecânicas Arcade em 2D',
    'home.sub1Html': 'Bem-vindo ao <strong>Typing Game Zone</strong>, o principal destino online para digitação gamificada. Ao contrário de testes monótonos em editores comuns, combinamos <strong>telemetria de PPM de nível laboratorial</strong> com jogos 2D envolventes.',
    'home.sub2Title': 'Por que Jogar Jogos de Digitação em 2D Online? O Poder da Gamificação',
    'home.sub2Html1': 'Dominar a <strong>digitação no computador</strong> requer a construção de memória muscular. Sob a urgência do jogo, o hábito de olhar para o teclado é eliminado, dando lugar a reflexos instantâneos.',
    'home.sub2Html2': 'Nossa coleção de <strong>jogos de digitação 2D online</strong> estimula a visão periférica e reflexos rápidos:',
    'home.sub2Card1Title': '🧟 Horda de Zumbis',
    'home.sub2Card1Desc': 'Mecânica de sobrevivência onde alta velocidade de digitação repele ondas inimigas.',
    'home.sub2Card2Title': '🐍 Arena da Cobrinha',
    'home.sub2Card2Desc': 'Navegação em labirinto retrô exigindo comandos imediatos de direção.',
    'home.sub2Card3Title': '🕵️ Adivinhe Quem Sou',
    'home.sub2Card3Desc': 'Pistas em enigmas e identificação dedutiva de palavras-chave contra o relógio.',
    'home.sub3Title': 'Lições Estruturadas e o Laboratório de Prática Interativo',
    'home.sub3Html': 'O posicionamento ergonômico das mãos é a base para ultrapassar 100 PPM. Nosso laboratório traz um mapa térmico da linha base (ASDF JKL;) para orientar cada dedo com precisão.',
    'home.sub4Title': 'Jogos de Digitação Divertidos para Crianças: Seguros e Educativos',
    'home.sub4Html': 'No mundo digital atual, a proficiência no teclado é uma habilidade fundamental. Nossos jogos são seguros, divertidos e estimulam o vocabulário e a ortografia.',
    'home.sub5Title': 'Dominando a Velocidade de Palavras e Testes de Referência',
    'home.sub5Html': 'Para atingir velocidades profissionais de 80 a 120+ PPM, o cérebro processa blocos inteiros de palavras ao invés de letras isoladas.',
