    'home.guideTitle': 'Padroneggia la Tastiera con Typing Game Zone: Il Portale Arcade Gratuito Definitivo',
    'home.guideSubtitle': 'Scopri come battaglie arcade 2D, test di velocità e dattilografia a dieci dita raddoppiano la tua agilità di battitura.',
    'home.sub1Title': 'Rivoluzionare la Dattilografia Online con Meccaniche Arcade 2D',
    'home.sub1Html': 'Benvenuto su <strong>Typing Game Zone</strong>, la principale piattaforma globale per la digitazione gamificata. A differenza dei noiosi simulatori testuali, uniamo <strong>telemetria WPM di livello scientifico</strong> a giochi 2D mozzafiato.',
