    'home.sub2Html1': 'Padroneggiare la <strong>dattilografia a dieci dita</strong> richiede lo sviluppo della memoria muscolare. Sotto la pressione del gioco, l’abitudine di guardare la tastiera viene superata, lasciando spazio a riflessi istintivi.',
    'home.sub2Html2': 'La nostra selezione di <strong>giochi di digitazione 2D online</strong> allena la vista periferica e i tempi di reazione:',
