    'home.sub2Card3Title': '🕵️ Indovina Chi Sono',
    'home.sub2Card3Desc': 'Indizi ed enigmi con digitazione deduttiva di parole chiave contro il tempo.',
    'home.sub3Title': 'Lezioni Strutturate e il Laboratorio Interattivo',
    'home.sub3Html': 'Una corretta postura ergonomica delle mani è fondamentale per superare i 100 WPM. Il nostro laboratorio offre una mappa termica della fila base (ASDF JKL;) per guidare ogni dito con precisione.',
    'home.sub4Title': 'Giochi di Dattilografia Divertenti per Ragazzi: Sicuri ed Educativi',
    'home.sub4Html': 'Nell’era digitale, la padronanza della tastiera è una competenza fondamentale per la scuola e il futuro. I nostri giochi sono sicuri, divertenti e arricchiscono il vocabolario.',
    'home.sub5Title': 'Dominare la Velocità delle Parole e i Benchmark per Esperti',
    'home.sub5Html': 'Per raggiungere velocità professionali tra 80 e oltre 120 WPM, il cervello elabora intere parole in blocchi (chunking). Il nostro test fornisce metriche dettagliate su consistenza e latenza.',
