    'game.rhythm-beat.title': '리듬 비트 타이퍼',
    'game.rhythm-beat.desc': '4레인 신스웨이브 음악 트랙. 빨라지는 BPM 템포에 맞춰 정확한 박자로 단어를 치세요.',
