    'home.guideBadge': '📖 키보드 완벽 마스터 가이드',
    'home.guideTitle': 'Typing Game Zone과 함께 키보드 완전 정복: 궁극의 무료 아케이드 포털',
    'home.guideSubtitle': '2D 아케이드 배틀, 속도 테스트, 체계적인 터치 타이핑이 타자 속도를 두 배 이상 향상시키는 비결.',
    'home.sub1Title': '2D 아케이드 메커니즘을 통한 온라인 타자 학습의 혁신',
    'home.sub1Html': '<strong>Typing Game Zone</strong>에 오신 것을 환영합니다. 지루한 텍스트 연습기와 달리, <strong>연구실 수준의 WPM 측정 기술</strong>과 몰입감 넘치는 2D 아케이드 게임을 결합했습니다.',
    'home.sub2Title': '왜 2D 타자 게임을 해야 할까요? 게이미피케이션의 힘',
    'home.sub2Html1': '컴퓨터 <strong>터치 타이핑</strong>을 마스터하려면 근육 기억 형성이 필수적입니다. 게임의 긴박함 속에서 키보드를 쳐다보는 습관이 사라지고 직관적인 반사신경이 완성됩니다.',
    'home.sub2Html2': '엄선된 <strong>2D 온라인 타자 게임</strong> 컬렉션은 주변 시야와 순간 반응 속도를 길러줍니다:',
    'home.sub2Card1Title': '🧟 좀비 호드',
    'home.sub2Card1Desc': '생존 탄막 배틀: 빠른 WPM 타자로 몰려드는 적을 퇴치합니다.',
    'home.sub2Card2Title': '🐍 스네이크 아레나',
    'home.sub2Card2Desc': '레트로 미로 탈출: 즉각적인 방향 전환 키 입력.',
    'home.sub2Card3Title': '🕵️ 내가 누구게?',
    'home.sub2Card3Desc': '수수께끼 단서에서 키워드를 추론하여 시간 내에 타이핑.',
    'home.sub3Title': '체계적인 타자 레슨과 인터랙티브 연습 랩',
    'home.sub3Html': '인체공학적 손가락 배치는 100+ WPM 돌파의 초석입니다. 연습 랩의 기본 자리(ASDF JKL;) 히트맵이 올바른 타건을 돕습니다.',
    'home.sub4Title': '어린이를 위한 재미있는 타자 게임: 안전하고 교육적인 환경',
    'home.sub4Html': '디지털 시대에 키보드 숙련도는 필수 기초 역량입니다. 본 플랫폼의 게임은 유해 요소가 없으며 어휘력과 맞춤법을 길러줍니다.',
    'home.sub5Title': '단어 입력 속도 극대화 및 타자 마스터 벤치마크 달성',
    'home.sub5Html': '80~120+ WPM의 프로 수준에 도달하려면 낱글자가 아닌 단어 전체를 한 덩어리로 인식하는 훈련이 필요합니다. 실시간 측정으로 정밀 분석을 확인하세요.',
    'home.sub6Title': 'Typing Game Zone이 모든 사람에게 100% 무료인 이유',
    'home.sub6Html': '우리는 최고 수준의 타자 교육과 아케이드 게임이 결제나 구독 없이 전 세계 누구나 브라우저에서 자유롭게 이용할 수 있어야 한다고 믿습니다.',
