    'game.gladiator-arena.title': 'Arena Gladiator',
    'game.gladiator-arena.desc': 'Pertarungan bertahan hidup di Colosseum melawan singa lapar, prajurit tombak, dan kereta perang.',
    'game.word-tetris.title': 'Tetris Kata',
    'game.word-tetris.desc': 'Ketik tetromino kata yang jatuh untuk melenyapkan balok sebelum menyentuh batas atas.',
    'game.rhythm-beat.title': 'Rhythm Beat Typer',
