    'game.speed-typer-pro.title': 'Speed Typer Pro',
    'game.speed-typer-pro.desc': 'Adu cepat sprint olimpiade dengan spedometer langsung melawan mobil hantu AI kompetitif.',
    'game.ghost-buster.title': 'Pemburu Hantu',
    'game.ghost-buster.desc': 'Arahkan sinar vakum proton ke hantu-hantu puri dan kunci mereka di dalam perangkap.',
