    'home.noviceTier': '🌱 Pemula: 0–35 WPM',
    'home.averageTier': '🎯 Rata-rata: 40–55 WPM',
    'home.proTier': '⚡ Pro: 60–85 WPM',
    'home.titanTier': '👑 Titan: 100+ WPM',
    'home.guideBadge': '📖 PANDUAN KEYBOARD LENGKAP',
    'home.guideTitle': 'Kuasai Keyboard dengan Typing Game Zone: Portal Arcade Gratis Terbaik',
    'home.guideSubtitle': 'Pelajari bagaimana pertarungan arcade 2D, uji kecepatan, dan mengetik 10 jari melipatgandakan kecepatan mengetikmu.',
    'home.sub1Title': 'Merevolusi Mengetik Online Melalui Mekanika Arcade 2D',
    'home.sub1Html': 'Selamat datang di <strong>Typing Game Zone</strong>, platform mengetik online berbasis game terdepan di dunia. Berbeda dengan editor teks membosankan, kami memadukan <strong>telemetri WPM standar lab</strong> dengan aksi 2D seru.',
    'home.sub2Title': 'Mengapa Memainkan Game Mengetik 2D? Kehebatan Belajar Gamifikasi',
    'home.sub2Html1': 'Menguasai <strong>mengetik 10 jari tanpa melihat</strong> membutuhkan pembentukan memori otot. Dalam desakan game, kebiasaan melihat tombol hilang dan berganti menjadi refleks cepat.',
    'home.sub2Html2': 'Koleksi <strong>game mengetik 2D online</strong> kami melatih penglihatan tepi dan kecepatan reaksi:',
    'home.sub2Card1Title': '🧟 Gerombolan Zombi',
    'home.sub2Card1Desc': 'Mekanika bertahan hidup: WPM tinggi memukul mundur gelombang zombi.',
    'home.sub2Card2Title': '🐍 Arena Ular',
    'home.sub2Card2Desc': 'Labirin retro: perubahan arah cepat dengan ketukan akurat.',
    'home.sub2Card3Title': '🕵️ Tebak Siapa Aku',
    'home.sub2Card3Desc': 'Petunjuk teka-teki & mengetik kata kunci deduktif berpacu dengan waktu.',
    'home.sub3Title': 'Pelajaran Terstruktur dan Laboratorium Latihan Interaktif',
    'home.sub3Html': 'Posisi tangan ergonomis adalah kunci menembus 100+ WPM. Laboratorium kami menyediakan peta panas baris utama (ASDF JKL;) untuk melatih setiap jari.',
    'home.sub4Title': 'Game Mengetik Seru untuk Anak-Anak: Aman, Mendidik, dan Asyik',
    'home.sub4Html': 'Di era digital, keahlian keyboard adalah kemampuan dasar yang penting. Game kami aman, mendidik, serta memperkaya kosakata dan ejaan anak.',
    'home.sub5Title': 'Menguasai Kecepatan Kata dan Tolok Ukur Pengetik Mahir',
    'home.sub5Html': 'Untuk mencapai kecepatan 80 hingga 120+ WPM, otak mengenali kata sebagai satu kesatuan utuh (chunking). Uji kecepatan kami memberikan metrik konsistensi yang mendalam.',
    'home.sub6Title': 'Mengapa Typing Game Zone Sepenuhnya Gratis untuk Semua Orang',
    'home.sub6Html': 'Kami percaya edukasi mengetik berkualitas dan game arcade terbaik harus dapat diakses secara gratis oleh siapa pun langsung dari peramban.',
