    'game.meteor-strike.desc': 'Gezegen savunma kalkanını tehdit eden alevli kuyruklu yıldızları ve enkazları parçala.',
    'game.retro-invaders.title': 'Retro 8-Bit İstilacılar',
    'game.retro-invaders.desc': 'Orijinal CRT piksel atari tarzı uzaylı yürüyüşü. İstilacıları vur ve gizemli UFO ları yakala.',
    'game.laser-turret.title': '360 Lazer Tareti',
    'game.laser-turret.desc': '360 derece döner raylı lazerle gelen yörünge dron sürülerini hedef al ve yok et.',
    'game.cyber-hacker.title': 'Siber Korsan',
    'game.cyber-hacker.desc': 'Şifreli kurumsal ağlara sız ve ICE takibi %100 e ulaşmadan önce Kuantum Çekirdeği devre dışı bırak.',
    'game.zombie-horde.title': 'Zombi Sürüsü',
    'game.zombie-horde.desc': 'Hızlı enfekteler, zırhlı canavarlar ve devasa Kolosa karşı barikatı savun.',
    'game.neon-ninja.title': 'Neon Ninja',
    'game.neon-ninja.desc': 'Uçan shurikenleri ve element fenerlerini şimşek hızında katana vuruşlarıyla ikiye böl.',
    'game.robo-rampage.title': 'Robot İsyanı',
    'game.robo-rampage.desc': 'Geleceğin metropolünde zırhlı bir savaş robotunu kontrol ederek asi titan dronları alt et.',
    'game.dungeon-escape.title': 'Zindandan Kaçış',
    'game.dungeon-escape.desc': 'Otomatik koşan maceracı: dikenli çukurların üzerinden atla, testerelerin altından kay ve Ejderhadan kaç.',
    'game.space-racer.title': 'Uzay Yarışçısı',
    'game.space-racer.desc': 'Hiper hızlı synthwave otoyol yarışı. Solucan deliklerinden geç ve rakiplerini geride bırak.',
    'game.sky-climber.title': 'Gökyüzü Tırmanıcısı',
    'game.sky-climber.desc': 'Yüzen bulutların ve zıpzıp mantarların üzerinden sıçrayarak kozmik yörüngeye yüksel.',
    'game.deep-sea.title': 'Derin Deniz Denizaltısı',
    'game.deep-sea.desc': 'Mariana Çukurunu sonar dalgalarıyla keşfet, ışıltılı deniz analarından ve Kraken den kaçın.',
    'game.street-fighter.title': 'Street Fighter Yazıcı',
