    'game.samurai-showdown.title': 'Samuray Düellosu',
    'game.samurai-showdown.desc': 'Gün batımında sinematik düello. İşareti bekle ve milisaniyelik hassasiyetle kılıcını savur.',
    'game.gladiator-arena.title': 'Gladyatör Arenası',
