    'game.word-tetris.title': 'Kelime Tetrisi',
    'game.word-tetris.desc': 'Düşen kelime bloklarını yazarak tavan sınırına ulaşmadan önce satırları temizle.',
    'game.rhythm-beat.title': 'Rhythm Beat Typer',
    'game.rhythm-beat.desc': '4 şeritli synthwave müzik pisti. Artan BPM temposuna uygun olarak kelimeleri ritimle yaz.',
    'game.speed-typer-pro.title': 'Hız Yazıcısı Pro',
