    'home.pillar1Title': 'Prosedürel Mekanik Ses',
    'home.pillar1Desc': 'Gerçek zamanlı sentezlenen tıklama sesleri. Cherry MX Blue, Holy Panda ve daktilo sesleri arasında anında geçiş yap.',
    'home.pillar2Title': 'Canlı Telemetri & Delta WPM',
    'home.pillar2Desc': 'Milisaniye altı tuş zamanlamasıyla brüt WPM, net WPM, doğruluk oranı ve vuruş ritmini anında hesaplar.',
    'home.pillar3Title': '105 Kademeli Seviye',
    'home.pillar3Desc': '21 oyunun her biri, 30 WPM başlangıç seviyesinden 100+ WPM titan düzeyine kadar 5 zorluk derecesi içerir.',
