    'home.guideBadge': '📖 KAPSAMLI KLAVYE REHBERİ',
    'home.guideTitle': 'Typing Game Zone ile Klavyede Ustalaş: En İyi Ücretsiz Atari Portalı',
    'home.guideSubtitle': '2D atari savaşlarının, hız testlerinin ve on parmak yazmanın klavye hızınızı nasıl ikiye katladığını keşfedin.',
    'home.sub1Title': '2D Atari Mekanikleriyle Çevrimiçi Yazma Deneyiminde Devrim',
    'home.sub1Html': 'Dünyanın önde gelen oyunlaştırılmış klavye portalı <strong>Typing Game Zone</strong> a hoş geldiniz. Sıkıcı metin alıştırmalarının aksine, <strong>laboratuvar düzeyinde WPM telemetrisini</strong> sürükleyici 2D oyunlarla buluşturuyoruz.',
    'home.sub2Title': 'Neden Çevrimiçi 2D Yazma Oyunları Oynamalısınız? Oyunlaştırmanın Gücü',
    'home.sub2Html1': 'Klavyede <strong>on parmak kör yazmada</strong> ustalaşmak kas hafızası geliştirmeyi gerektirir. Oyun heyecanı içinde klavyeye bakma alışkanlığı son bulur ve yerini reflekslere bırakır.',
    'home.sub2Html2': 'Özenle seçilmiş <strong>2D çevrimiçi yazma oyunları</strong> koleksiyonumuz çevresel görüşü ve tepki hızını geliştirir:',
    'home.sub2Card1Title': '🧟 Zombi Sürüsü',
    'home.sub2Card1Desc': 'Hayatta kalma mekaniği: Yüksek WPM düşman dalgalarını püskürtür.',
    'home.sub2Card2Title': '🐍 Yılan Arenası',
    'home.sub2Card2Desc': 'Retro labirent: Anlık tuş vuruşlarıyla keskin dönüşler.',
    'home.sub2Card3Title': '🕵️ Bil Bakalım Kimim',
    'home.sub2Card3Desc': 'İpuçlarından kelimeleri çıkararak zamana karşı yazma.',
    'home.sub3Title': 'Yapılandırılmış Dersler ve Etkileşimli Alıştırma Laboratuvarı',
    'home.sub3Html': 'Ergonomik el duruşu 100+ WPM ye ulaşmanın temelidir. Laboratuvarımız temel sıra (ASDF JKL;) ısı haritasıyla her parmağı doğru tuşa yönlendirir.',
    'home.sub4Title': 'Çocuklar İçin Eğlenceli Yazma Oyunları: Güvenli ve Eğitici',
    'home.sub4Html': 'Dijital çağda klavye yetkinliği vazgeçilmez bir temel beceridir. Oyunlarımız güvenli, eğlenceli olup kelime dağarcığını ve doğru yazımı pekiştirir.',
    'home.sub5Title': 'Kelime Hızını Yönetme ve Klavye Ustalığı Standartları',
    'home.sub5Html': '80 ila 120+ WPM hızlarına ulaşmak için beyin harfleri tek tek değil, kelimeleri bütün bloklar halinde işler. Canlı test masamız hız analizini anında sunar.',
    'home.sub6Title': 'Typing Game Zone Neden Herkes İçin Tamamen Ücretsizdir',
    'home.sub6Html': 'Dünya çapında kaliteli klavye eğitiminin ve harika atari oyunlarının hiçbir ücret veya abonelik olmadan herkesin tarayıcısından erişilebilir olması gerektiğine inanıyoruz.',
